dbt_macro.macro:
{% macro helix_suppress(value, cell_count, threshold=5) %}
  CASE
    WHEN {{ cell_count }} < {{ threshold }} THEN NULL
    ELSE {{ value }}
  END
{% endmacro %}

{# Usage in a model: #}
{# SELECT #}
{#   race_ethnicity, #}
{#   {{ helix_suppress('COUNT(*)', 'COUNT(*)', 5) }} AS student_count, #}
{#   {{ helix_suppress( #}
{#     'ROUND(SUM(CASE WHEN graduated THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(*), 0), 1)', #}
{#     'COUNT(*)', #}
{#     5 #}
{#   ) }} AS graduation_rate #}
{# FROM {{ ref('silver_cohort_graduation') }} #}
{# GROUP BY race_ethnicity #}

dbt_macro.rounded_variant:
{% macro helix_suppress_rounded(value, cell_count, threshold=5, round_to=5) %}
  CASE
    WHEN {{ cell_count }} < {{ threshold }} THEN NULL
    ELSE ROUND({{ value }} / {{ round_to }}.0, 0) * {{ round_to }}
  END
{% endmacro %}
